/**
 * The configured menus as Nuxt UI items (ADR-015). A section becomes a group, its label
 * a `type: 'label'` item; `to` becomes a route, `action` an `onSelect`, an item without
 * either opens the layout's placeholder route. A route names the item it belongs to in
 * `meta.menu`: that item is active and its parent open. Generated by forge.
 */
import { computed, inject, provide, ref, type ComputedRef, type InjectionKey, type Ref } from 'vue'
import { useRoute, type RouteLocationNormalizedLoaded } from 'vue-router'
import type { DropdownMenuItem, NavigationMenuItem } from '@nuxt/ui'
import { application } from './config'
import { runAction } from './context'
import type { ApplicationConfig, MenuItemConfig, MenuName } from './contracts'

export type MenuBadges = Record<string, number | string | null | undefined>

const BADGES: InjectionKey<Ref<MenuBadges>> = Symbol('application-menu-badges')

/** Supply the values of the badge keys the menus name; call it in the layout wrapper or App. */
export function provideMenuBadges(values: Ref<MenuBadges>): void {
  provide(BADGES, values)
}

/** The id in the deepest matched route's `meta.menu`, or null. */
export function activeMenuItem(route: Pick<RouteLocationNormalizedLoaded, 'matched'>): string | null {
  for (let i = route.matched.length - 1; i >= 0; i -= 1) {
    const id = route.matched[i]?.meta?.menu
    if (typeof id === 'string' && id) return id
  }
  return null
}

function contains(item: MenuItemConfig, id: string | null): boolean {
  return id !== null && (item.id === id || (item.children ?? []).some(child => contains(child, id)))
}

/** The items of one menu of one layout, grouped by section. */
export function buildMenu(
  layout: string,
  menu: MenuName,
  { active = null, badges = {}, application: app = application }: { active?: string | null, badges?: MenuBadges, application?: ApplicationConfig } = {},
): NavigationMenuItem[][] {
  const config = app.layouts[layout]
  if (!config) throw new Error(`Unknown layout '${layout}'.`)

  function toItem(item: MenuItemConfig): NavigationMenuItem {
    const result: NavigationMenuItem = { label: item.label, value: item.id }
    if (item.icon) result.icon = item.icon
    const badge = item.badge ? badges[item.badge] : undefined
    if (badge !== undefined && badge !== null && badge !== '') result.badge = badge
    if (item.children?.length) {
      result.children = item.children.map(toItem)
      result.defaultOpen = contains(item, active)
      return result
    }
    if (item.action) {
      const action = item.action
      result.onSelect = () => {
        runAction(action)
      }
      return result
    }
    if (item.to) result.to = { name: item.to }
    else if (config!.placeholder) result.to = { name: config!.placeholder, params: { item: item.id } }
    else result.disabled = true
    // A route that names its item wins over link matching, so one item is active.
    if (active !== null) result.active = item.id === active
    return result
  }

  return config.menus[menu].map(section => [
    ...(section.label ? [{ type: 'label' as const, label: section.label }] : []),
    ...section.items.map(toItem),
  ])
}

/** One menu of one layout, following the current route and the badges provided. */
export function useApplicationMenu(layout: string, menu: MenuName): ComputedRef<NavigationMenuItem[][]> {
  const route = useRoute()
  const badges = inject(BADGES, ref<MenuBadges>({}))
  return computed(() => buildMenu(layout, menu, { active: activeMenuItem(route), badges: badges.value }))
}

function toDropdown(item: NavigationMenuItem): DropdownMenuItem {
  const { label, icon, to, onSelect, disabled, type, children } = item
  const result: DropdownMenuItem = { label, icon, to, onSelect, disabled, type: type === 'label' ? 'label' : undefined }
  if (children?.length) result.children = children.map(child => toDropdown(child as NavigationMenuItem))
  return result
}

/** One menu of one layout as `UDropdownMenu` items (the account menu, for example). */
export function useApplicationDropdown(layout: string, menu: MenuName): ComputedRef<DropdownMenuItem[][]> {
  const items = useApplicationMenu(layout, menu)
  return computed(() => items.value.map(group => group.map(toDropdown)))
}
